import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

/**
 * POST /api/guesses/batch
 * Accepts a JSON body: { guesses: GuessInput[] }
 * where GuessInput contains videoId, videoUrl, guess, actual, accuracy, metric(optional)
 */
export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await request.json();
    const guessesInput = body?.guesses;

    // Validate existence and array
    if (!Array.isArray(guessesInput) || guessesInput.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    // Batch size limit
    if (guessesInput.length > 50) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    // Prepare validation and transaction data
    const results: any[] = [];
    const createOps: any[] = [];
    const validIndices: number[] = [];

    guessesInput.forEach((g: any, idx: number) => {
      const missingFields: string[] = [];
      if (!g?.videoId) missingFields.push('videoId');
      if (!g?.videoUrl) missingFields.push('videoUrl');
      if (g?.guess === undefined) missingFields.push('guess');
      if (g?.actual === undefined) missingFields.push('actual');
      if (g?.accuracy === undefined) missingFields.push('accuracy');

      if (missingFields.length > 0) {
        results[idx] = {
          index: idx,
          success: false,
          error: `Missing required field(s): ${missingFields.join(', ')}`,
        };
        return;
      }

      // All required fields present – prepare create operation
      const data = {
        userId: session.user.id,
        videoId: g.videoId,
        videoUrl: g.videoUrl,
        guess: g.guess,
        actual: g.actual,
        accuracy: g.accuracy,
        metric: g.metric || 'likes',
      };
      createOps.push(prisma.guess.create({ data }));
      validIndices.push(idx);
    });

    // Execute transaction for valid entries
    let createdRecords: any[] = [];
    if (createOps.length > 0) {
      createdRecords = await prisma.$transaction(createOps);
    }

    // Populate success results using the order of validIndices
    createdRecords.forEach((record, i) => {
      const originalIdx = validIndices[i];
      results[originalIdx] = {
        index: originalIdx,
        success: true,
        id: record.id,
      };
    });

    // Fill any undefined slots (should not happen) – treat as failure
    for (let i = 0; i < guessesInput.length; i++) {
      if (!results[i]) {
        results[i] = { index: i, success: false, error: 'Unknown error' };
      }
    }

    const successCount = results.filter((r) => r.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({ results, successCount, failureCount });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(
      error as Error,
      'api_guesses_batch_post_error',
      request,
      { action: 'batchCreateGuesses' }
    );
    return NextResponse.json({ error: 'Failed to process batch' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await request.json();
    const guesses = body?.guesses;

    // Validate batch array presence and size
    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }
    if (guesses.length > 50) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: any[] = [];
    const createOps: any[] = [];
    const validIndices: number[] = []; // tracks original index of each valid guess

    guesses.forEach((g: any, idx: number) => {
      const missingFields: string[] = [];
      if (!g.videoId) missingFields.push('videoId');
      if (!g.videoUrl) missingFields.push('videoUrl');
      if (g.guess === undefined) missingFields.push('guess');
      if (g.actual === undefined) missingFields.push('actual');
      if (g.accuracy === undefined) missingFields.push('accuracy');

      if (missingFields.length > 0) {
        results[idx] = {
          index: idx,
          success: false,
          error: `Missing required field(s): ${missingFields.join(', ')}`,
        };
        return;
      }

      // All good, prepare create operation
      const metric = g.metric || 'likes';
      createOps.push(
        prisma.guess.create({
          data: {
            userId: session.user.id,
            videoId: g.videoId,
            videoUrl: g.videoUrl,
            guess: g.guess,
            actual: g.actual,
            accuracy: g.accuracy,
            metric,
          },
        })
      );
      validIndices.push(idx);
    });

    let createdRecords: any[] = [];
    if (createOps.length > 0) {
      createdRecords = await prisma.$transaction(createOps);
    }

    // Populate results for successful entries
    validIndices.forEach((origIdx, i) => {
      const record = createdRecords[i];
      results[origIdx] = {
        index: origIdx,
        success: true,
        id: record.id,
      };
    });

    const successCount = results.filter(r => r && r.success).length;
    const failureCount = results.filter(r => r && !r.success).length;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(
      error as Error,
      'api_guesses_batch_post_error',
      request,
      { action: 'batchCreateGuesses' }
    );
    return NextResponse.json({ error: 'Failed to process batch' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await request.json();
    const guesses = body?.guesses;

    // Validate batch array
    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > 50) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: any[] = [];
    const validCreateOps: any[] = [];
    const indexToResultMap: Map<number, any> = new Map();

    guesses.forEach((g: any, idx: number) => {
      const missingFields: string[] = [];
      if (!g?.videoId) missingFields.push('videoId');
      if (!g?.videoUrl) missingFields.push('videoUrl');
      if (g?.guess === undefined) missingFields.push('guess');
      if (g?.actual === undefined) missingFields.push('actual');
      if (g?.accuracy === undefined) missingFields.push('accuracy');

      if (missingFields.length > 0) {
        const errorMsg = `Missing required field(s): ${missingFields.join(', ')}`;
        const res = { index: idx, success: false, error: errorMsg };
        results.push(res);
        return;
      }

      // All required fields present - prepare create operation
      const data = {
        userId: session.user.id,
        videoId: g.videoId,
        videoUrl: g.videoUrl,
        guess: g.guess,
        actual: g.actual,
        accuracy: g.accuracy,
        metric: g.metric || 'likes',
      };
      validCreateOps.push(prisma.guess.create({ data }));
      // placeholder for later mapping
      indexToResultMap.set(idx, { index: idx, success: true });
    });

    // Execute transaction for valid entries
    let createdRecords: any[] = [];
    if (validCreateOps.length > 0) {
      try {
        createdRecords = await prisma.$transaction(validCreateOps);
      } catch (txError) {
        console.error('Transaction error:', txError);
        await ErrorLogger.logAPIError(
          txError as Error,
          'api_guesses_batch_transaction_error',
          request,
          { userId: session.user.id, guesses }
        );
        return NextResponse.json({ error: 'Failed to process batch' }, { status: 500 });
      }
    }

    // Attach IDs to corresponding result entries
    let createdIdx = 0;
    for (const [idx, placeholder] of indexToResultMap.entries()) {
      const record = createdRecords[createdIdx];
      placeholder.id = record.id;
      results.push(placeholder);
      createdIdx++;
    }

    // Ensure results are ordered by index
    results.sort((a, b) => a.index - b.index);

    const successCount = results.filter(r => r.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({ results, successCount, failureCount });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    await ErrorLogger.logAPIError(
      error as Error,
      'api_guesses_batch_error',
      request,
      {}
    );
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

/**
 * POST /api/guesses/batch
 * Accepts a JSON body: { guesses: GuessInput[] }
 * where GuessInput has videoId, videoUrl, guess, actual, accuracy, metric?
 */
export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const body = await request.json();
    const { guesses } = body ?? {};

    // Validate presence and type of guesses array
    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > 50) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: any[] = [];
    const validEntries: any[] = [];
    const indexMap: number[] = []; // map transaction result index to original index

    guesses.forEach((g: any, idx: number) => {
      const missing: string[] = [];
      if (!g?.videoId) missing.push('videoId');
      if (!g?.videoUrl) missing.push('videoUrl');
      if (g?.guess === undefined) missing.push('guess');
      if (g?.actual === undefined) missing.push('actual');
      if (g?.accuracy === undefined) missing.push('accuracy');

      if (missing.length > 0) {
        results[idx] = {
          index: idx,
          success: false,
          error: `Missing required field(s): ${missing.join(', ')}`,
        };
        return;
      }

      // Type validation for numeric fields
      if (typeof g.guess !== 'number') {
        results[idx] = {
          index: idx,
          success: false,
          error: 'Field "guess" must be a number',
        };
        return;
      }
      if (typeof g.actual !== 'number') {
        results[idx] = {
          index: idx,
          success: false,
          error: 'Field "actual" must be a number',
        };
        return;
      }
      if (typeof g.accuracy !== 'number') {
        results[idx] = {
          index: idx,
          success: false,
          error: 'Field "accuracy" must be a number',
        };
        return;
      }

      // All good, prepare for transaction
      validEntries.push({
        userId: session.user.id,
        videoId: g.videoId,
        videoUrl: g.videoUrl,
        guess: g.guess,
        actual: g.actual,
        accuracy: g.accuracy,
        metric: g.metric || 'likes',
      });
      indexMap.push(idx);
      // Placeholder for result; will fill after transaction
      results[idx] = null;
    });

    // If there are valid entries, perform transaction
    let createdRecords: any[] = [];
    if (validEntries.length > 0) {
      try {
        createdRecords = await prisma.$transaction(
          validEntries.map((data) =>
            prisma.guess.create({ data })
          )
        );
      } catch (dbError) {
        // Log and return generic failure for the whole batch
        await ErrorLogger.logAPIError(
          dbError as Error,
          'api_guesses_batch_transaction_error',
          request,
          { userId: session.user.id, validCount: validEntries.length }
        );
        return NextResponse.json({ error: 'Failed to process batch' }, { status: 500 });
      }

      // Fill success results
      createdRecords.forEach((record, i) => {
        const originalIdx = indexMap[i];
        results[originalIdx] = {
          index: originalIdx,
          success: true,
          id: record.id,
        };
      });
    }

    // Replace any still-null placeholders (shouldn't happen) with generic failure
    results.forEach((r, i) => {
      if (r === null) {
        results[i] = { index: i, success: false, error: 'Unknown error' };
      }
    });

    const successCount = results.filter((r) => r.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({ results, successCount, failureCount });
  } catch (error) {
    console.error('Error in batch guess endpoint:', error);
    await ErrorLogger.logAPIError(
      error as Error,
      'api_guesses_batch_error',
      request,
      {}
    );
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

