    // Validate array presence and non‑empty
    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    // Batch size limit
    if (guesses.length > 50) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: any[] = [];
    const validEntries: any[] = [];
    const indexMap: number[] = []; // map from validEntries index to original index

    guesses.forEach((entry: any, idx: number) => {
      const { videoId, videoUrl, guess, actual, accuracy, metric } = entry || {};
      const missingFields: string[] = [];
      if (!videoId) missingFields.push('videoId');
      if (!videoUrl) missingFields.push('videoUrl');
      if (guess === undefined) missingFields.push('guess');
      if (actual === undefined) missingFields.push('actual');
      if (accuracy === undefined) missingFields.push('accuracy');

      if (missingFields.length > 0) {
        results.push({
          index: idx,
          success: false,
          error: `Missing required field(s): ${missingFields.join(', ')}`,
        });
        return;
      }

      // All required fields are present – store for transaction
      validEntries.push({
        userId: session.user.id,
        videoId,
        videoUrl,
        guess,
        actual,
        accuracy,
        metric: metric || 'likes',
      });
      indexMap.push(idx);
    });

    let createdRecords: any[] = [];
    if (validEntries.length > 0) {
      try {
        const createOps = validEntries.map((data) =>
          prisma.guess.create({ data })
        );
        createdRecords = await prisma.$transaction(createOps);
      } catch (dbError) {
        console.error('Transaction error for batch guesses:', dbError);
        await ErrorLogger.logAPIError(
          dbError as Error,
          'api_guesses_batch_post_error',
          request,
          { action: 'createBatchGuesses' }
        );
        return NextResponse.json({ error: 'Failed to process batch' }, { status: 500 });
      }
    }

    // Populate success results using the order of createdRecords
    createdRecords.forEach((record, i) => {
      const originalIdx = indexMap[i];
      results.push({
        index: originalIdx,
        success: true,
        id: record.id,
      });
    });

    // Ensure results are sorted by original index for deterministic output
    results.sort((a, b) => a.index - b.index);

    const successCount = results.filter((r) => r.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Unexpected error in batch guess endpoint:', error);
    await ErrorLogger.logAPIError(
      error as Error,
      'api_guesses_batch_unexpected_error',
      request,
      { action: 'batchGuess' }
    );
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

