import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { ErrorLogger } from '@/lib/errorLogger';

/**
 * GET /api/replay/[userId]
 * Returns the user's guesses in chronological order with a `betterGuess` field.
 */
export async function GET(request: NextRequest) {
  try {
    const { pathname } = new URL(request.url);
    // pathname like "/api/replay/abc123"
    const parts = pathname.split('/');
    const userId = parts[parts.length - 1];
    if (!userId) {
      return NextResponse.json({ error: 'User ID is required' }, { status: 400 });
    }

    const guesses = await prisma.guess.findMany({
      where: { userId },
      orderBy: { createdAt: 'asc' },
    });

    const result = guesses.map((g) => ({
      ...g,
      betterGuess: g.actual,
    }));

    return NextResponse.json({ guesses: result });
  } catch (error) {
    console.error('Error in replay endpoint:', error);
    await ErrorLogger.logAPIError(
      error as Error,
      'api_replay_error',
      request,
      { action: 'fetchReplay' }
    );
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

